        }
    }

    return new
    {
        success = true,
        source = src.name,
        target = tgt.name,
        sourceCount = srcMesh.blendShapeCount,
        targetCount = tgtMesh.blendShapeCount,
        matchedCount = matched,
        missingOnTarget = report.Take(50).ToList()
    };
}
